async function copyCodeToClipboard(e,t){const o=t.querySelector("pre.src").textContent.trim();await navigator.clipboard.writeText(o),e.innerText="Copied",setTimeout(function(){e.innerText="Copy"},2e3)}function createCopyButton(e){const t=document.createElement("button");t.className="copy-code",t.type="button",t.ariaLabel="Copy",t.innerText="Copy",t.addEventListener("click",()=>copyCodeToClipboard(t,e)),e.appendChild(t)}function scrollTop(){var e=document.getElementById("top-link");window.addEventListener("scroll",()=>{document.body.scrollTop>50||document.documentElement.scrollTop>50?(e.style.visibility="visible",e.style.opacity="1"):(e.style.visibility="hidden",e.style.opacity="0")},{passive:!0})}function sidenotes(){document.querySelectorAll(".footref").forEach(e=>{const t=document.getElementById(e.hash.substring(1)),o=t&&t.closest(".footdef"),n=o&&o.querySelector(":scope > .footpara");if(!n)return;const i=document.createElement("span");i.classList.add("sidenote"),i.setAttribute("role","note"),i.innerHTML=t.innerText+". "+n.innerHTML,(e.closest("sup")||e).after(i)})}window.addEventListener("DOMContentLoaded",e=>{var t=document.getElementById("menu-button"),o=document.getElementById("menu-list");t.addEventListener("click",()=>{o.classList.toggle("!block")})}),window.addEventListener("DOMContentLoaded",e=>{document.querySelectorAll(".org-src-container").forEach(e=>createCopyButton(e))}),window.addEventListener("DOMContentLoaded",e=>{scrollTop()}),window.addEventListener("DOMContentLoaded",e=>{sidenotes()});